import json, sys, time, urllib.request, urllib.error, os

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
token = None

def log(*a):
    print(*a, file=sys.stderr, flush=True)

def raw(path, auth):
    headers = {}
    if auth:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(BASE + path, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()

def fetch_token():
    global token
    status, _, body = raw_post("/token")
    if status != 200:
        raise RuntimeError(f"token failed: {status} {body[:200]}")
    token = json.loads(body)["token"]
    log("token refreshed")

def raw_post(path):
    req = urllib.request.Request(BASE + path, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()

def get(path, auth=True, max_attempts=60):
    """GET with retry. Returns (status, parsed_json_or_None). 404 returns (404, None)."""
    global token
    if auth and token is None:
        fetch_token()
    for attempt in range(1, max_attempts + 1):
        try:
            status, headers, body = raw(path, auth)
        except OSError as e:
            log(f"[{path}] network error attempt {attempt}: {e}")
            time.sleep(min(2 ** attempt, 20))
            continue
        if status == 200:
            return 200, json.loads(body)
        if status == 404:
            return 404, None
        text = body[:300].decode("utf-8", "replace")
        if status == 401 or status == 403:
            log(f"[{path}] {status} attempt {attempt}: {text}; refreshing token")
            fetch_token()
            continue
        if status == 429:
            ra = headers.get("Retry-After")
            log(f"[{path}] 429 attempt {attempt}: Retry-After={ra!r} body={text!r}")
            wait = float(ra) if ra and ra.replace('.', '', 1).isdigit() else 5.0
            time.sleep(wait)
            continue
        if status >= 500:
            log(f"[{path}] {status} attempt {attempt}: {text}")
            time.sleep(min(2 ** attempt, 20))
            continue
        log(f"[{path}] unexpected {status}: {text}")
        time.sleep(2)
    raise RuntimeError(f"gave up on {path}")

def save(name, obj):
    with open(os.path.join(DATA, name), "w") as f:
        json.dump(obj, f)

def main():
    # Orders: follow "next" until null, saving each page as received.
    path = "/orders?page=1"
    pages = 0
    while path:
        status, page = get(path)
        assert status == 200
        pages += 1
        save(f"page-{pages:03d}.json", {"requested": path, "response": page})
        log(f"page {pages}: requested {path} -> page={page['page']} "
            f"total_pages={page['total_pages']} items={len(page['items'])} next={page['next']}")
        path = page["next"]
    log(f"fetched {pages} pages")

    # Customers: fetch each distinct customer_id once.
    cust_ids = set()
    for fn in sorted(os.listdir(DATA)):
        if fn.startswith("page-"):
            with open(os.path.join(DATA, fn)) as f:
                for it in json.load(f)["response"]["items"]:
                    cust_ids.add(it["customer_id"])
    log(f"distinct customers: {len(cust_ids)}")
    customers = {}
    for cid in sorted(cust_ids):
        status, rec = get(f"/customers/{cid}")
        customers[cid] = rec if status == 200 else {"_status": status}
        if status != 200:
            log(f"customer {cid}: status {status}")
    save("customers.json", customers)
    log("done")

if __name__ == "__main__":
    main()
